/* Local-only form review helpers. Never serialize user fields to URLs or services. */
window.SportsForms=(()=>{
 const node=(tag,text,attrs={})=>{const el=document.createElement(tag);if(text!==undefined)el.textContent=text;Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));return el;};
 function clearErrors(form){form.querySelectorAll('[aria-invalid]').forEach(el=>{el.removeAttribute('aria-invalid');const ids=(el.getAttribute('aria-describedby')||'').split(' ').filter(id=>!id.startsWith('error-'));ids.length?el.setAttribute('aria-describedby',ids.join(' ')):el.removeAttribute('aria-describedby');});form.querySelectorAll('.field-error').forEach(el=>el.remove());const summary=form.querySelector('.error-summary');if(summary){summary.hidden=true;summary.replaceChildren();}}
 function errors(form,items){clearErrors(form);const entries=Object.entries(items);if(!entries.length)return false;const summary=form.querySelector('.error-summary');summary.append(node('h3','Check your details.'),node('p','Nothing has been sent.'));const ul=node('ul');entries.forEach(([id,text])=>{const el=document.getElementById(id);if(!el)return;el.setAttribute('aria-invalid','true');const error=node('span',text,{id:'error-'+id,class:'field-error'});el.setAttribute('aria-describedby',((el.getAttribute('aria-describedby')||'')+' '+error.id).trim());const anchor=el.closest('.court-choices,.winner-choices')||el;anchor.insertAdjacentElement('afterend',error);const li=node('li'),a=node('a',text,{href:'#'+id});a.addEventListener('click',ev=>{ev.preventDefault();el.focus();});li.append(a);ul.append(li);});summary.append(ul);summary.hidden=false;summary.focus();return true;}
 function required(form){const problems={};[...form.elements].filter(el=>el.required&&!el.disabled&&el.type!=='radio').forEach(el=>{const label=el.dataset.label||el.labels?.[0]?.textContent.split('*')[0].trim()||'This field';if(el.type==='checkbox'&&!el.checked)problems[el.id]='Please confirm that you have read the archived rules.';else if(!el.value.trim())problems[el.id]=`Enter ${label.toLowerCase()}.`;else if(el.type==='email'&&el.validity.typeMismatch)problems[el.id]='Enter an email address in the format name@example.com.';else if(el.type==='number'&&!el.validity.valid)problems[el.id]=`Enter a whole number between ${el.min||'0'} and ${el.max||'the number of listed players'}.`;});return problems;}
 function review(el,values){const dl=el.querySelector('dl');dl.replaceChildren();values.forEach(([label,value])=>{const row=node('div');row.append(node('dt',label),node('dd',String(value)));dl.append(row);});el.hidden=false;el.focus();el.scrollIntoView({block:'start',behavior:'instant'});}
 function istDate(offset=0){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const a=Object.fromEntries(parts.map(p=>[p.type,p.value]));return new Date(Date.UTC(+a.year,+a.month-1,+a.day+offset)).toISOString().slice(0,10);}
 return {node,errors,clearErrors,required,review,istDate};
})();
